cmd:
cat > /etc/nginx/conf.d/benchmark-site.conf << 'EOF'
server {
    listen 8080;
    listen [::]:8080;
    server_name _;

    root /var/www/html;
    index index.html;

    # Detailed request logging
    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log;

    # Rate limiting: 10 r/s per IP with burst of 10
    limit_req zone=benchmark_limit burst=10;

    # Custom 404 error page
    error_page 404 /404.html;

    location / {
        try_files $uri $uri/ =404;
    }
}
EOF
cat /etc/nginx/conf.d/benchmark-site.conf

tee /etc/nginx/conf.d/benchmark-site.conf << 'EOF' > /dev/null
